import bisect, hashlib

def h(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16)

class Ring:
    def __init__(self, nodes):
        self.points = sorted((h(n), n) for n in nodes)

    def owner(self, key):
        hashes = [p for p, _ in self.points]
        i = bisect.bisect_left(hashes, h(key))  # first token >= key
        return self.points[i % len(self.points)][1]  # wrap around

ring = Ring(["cache-a", "cache-b", "cache-c"])
print(ring.owner("user:42"))

import random, zlib

SUFFIXES = 20   # 10,000 writes/s / 1,000 per partition = 10, doubled for headroom

def write_key(day):
    # random suffix: best spread, but a reader cannot find one item by id
    return f"{day}.{random.randint(1, SUFFIXES)}"

def write_key_for(day, order_id):
    # calculated suffix: same spread, and a GetItem can recompute it
    return f"{day}.{zlib.crc32(order_id.encode()) % SUFFIXES + 1}"

def keys_to_read_whole_day(day):
    return [f"{day}.{n}" for n in range(1, SUFFIXES + 1)]  # fan-out + merge
